/**
 * The result of a transcription.
 */
public struct TranscriptionResult {
    public var text: String
    public var language: String
    public var segments: [TranscriptionSegment]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(text: String, language: String, segments: [TranscriptionSegment]) {
        self.text = text
        self.language = language
        self.segments = segments
    }
}

extension TranscriptionResult: Equatable, Hashable {
    public static func == (lhs: TranscriptionResult, rhs: TranscriptionResult) -> Bool {
        if lhs.text != rhs.text {
            return false
        }
        if lhs.language != rhs.language {
            return false
        }
        if lhs.segments != rhs.segments {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(text)
        hasher.combine(language)
        hasher.combine(segments)
    }
}

